// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io/
// https://twitter.com/KaufmanRoni

var n = 2, u, sw = 5;
var palette, backCol, strokeCol;

function setup() {
  createCanvas(512, 512);
  // noLoop() removed for animation
  if (random() < 1/2) {
    palette = ["#f23c3c", "#f2973c", "#f2f23c", "#3cf23c", "#3cf2f2", "#3c3cf2", "#f23cf2"];
    backCol = "#000b28";
    strokeCol = 250;
  } else {
    palette = ["#000b28"];
    backCol = 250;
    strokeCol = "#000b28";
  }
  strokeWeight(sw);
  noFill();
  pixelDensity(1);
  strokeCap(PROJECT);
}

function draw() {
  translate(-width/2, -height/2);
  scale(0.5);
  translate(width+sw, height+sw);
  scale(2*(width-sw)/width);
  background(backCol);
  stroke(strokeCol);
  square(0, 0, width);

  let g = 3*(pow(2, n+1) - 1); // grid size
  u = width/g; // grid unit block
  let s = u;
  let offset = u;

  for (let i = 0; i < n; i++) {
    for (let x = offset; x < width-offset-2*s; x += (Math.max(0.001, Math.abs(s+u)) || 1)) {
      makeSquare(x, offset, s);
      makeSquare(offset, x+s+u, s);
      makeSquare(width-offset-s, x, s);
      makeSquare(x+s+u, height-offset-s, s);
    }
    offset += s + u;
    s = 2*s+u;
  }
  makeSquare(offset, offset, s);
}

function makeSquare(x0, y0, s) {
  let r = floor(random(6));
  for (let i = 0; i < r; i++) palette.unshift(palette.pop());
  let id = random(2);
  push();
  translate(x0+s/2, y0+s/2);
  rotate(random([0, PI/2, PI, 3*PI/2]));
  let i = 0;
  for (let c = s; c > 0; c -= u/2) {
    stroke(palette[(i++)%palette.length]);
    if (id < 1) square(-s/2, -s/2, c);
    else arc(-s/2, -s/2, 2*c, 2*c, 0, PI/2, PIE);
  }
  stroke(strokeCol);
  line(-s/2, -s/2, s/2, -s/2);
  line(-s/2, -s/2, -s/2, s/2);
  pop();
}
